data.transactional-002_sale_publication.sql:
BEGIN;
SELECT pg_advisory_xact_lock(1);
SET LOCAL ROLE flash_sale_app;
CREATE TABLE IF NOT EXISTS flash_sale.drafts (
    sale_id text PRIMARY KEY,
    terms jsonb NOT NULL,
    state text NOT NULL DEFAULT 'DRAFT' CHECK (state IN ('DRAFT','PENDING','PUBLISHED')),
    operation_id text UNIQUE,
    origin text CHECK (origin IN ('a','b','c','d')),
    step smallint NOT NULL DEFAULT 0 CHECK (step BETWEEN 0 AND 4),
    envelope bytea,
    next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    correlation_id text,
    CHECK ((state = 'DRAFT') = (operation_id IS NULL)),
    CHECK ((operation_id IS NULL) = (origin IS NULL)),
    CHECK ((step >= 2) = (envelope IS NOT NULL)),
    CHECK ((step = 4) = (state = 'PUBLISHED'))
);
CREATE INDEX IF NOT EXISTS drafts_pending ON flash_sale.drafts (next_attempt_at, sale_id) WHERE state='PENDING';
RESET ROLE;
SET LOCAL ROLE inventory_app;
CREATE TABLE IF NOT EXISTS inventory.sales (
    sale_id text PRIMARY KEY,
    operation_id text NOT NULL UNIQUE,
    terms jsonb NOT NULL,
    available_stock bigint NOT NULL CHECK (available_stock >= 0),
    active boolean NOT NULL DEFAULT false
);
COMMIT;

BEGIN;
SELECT pg_advisory_xact_lock(1);
SET LOCAL ROLE admission_app;
CREATE TABLE IF NOT EXISTS admission.attempts (
    attempt_id text PRIMARY KEY,
    sale_id text NOT NULL,
    customer_id text NOT NULL
);
CREATE TABLE IF NOT EXISTS admission.purchase_outbox (
    attempt_id text PRIMARY KEY REFERENCES admission.attempts,
    body jsonb NOT NULL,
    next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    sent_at timestamptz
);
CREATE INDEX IF NOT EXISTS purchase_outbox_pending
    ON admission.purchase_outbox(next_attempt_at, attempt_id) WHERE sent_at IS NULL;
CREATE TABLE IF NOT EXISTS admission.events (
    event_id text PRIMARY KEY,
    body jsonb NOT NULL
);
RESET ROLE;
SET LOCAL ROLE inventory_app;
CREATE TABLE IF NOT EXISTS inventory.attempts (
    attempt_id text PRIMARY KEY,
    sale_id text NOT NULL,
    customer_id text NOT NULL,
    rejection text CHECK (rejection IN ('INACTIVE','ENDED','SOLD_OUT'))
);
CREATE TABLE IF NOT EXISTS inventory.reservations (
    reservation_id text PRIMARY KEY REFERENCES inventory.attempts(attempt_id),
    sale_id text NOT NULL REFERENCES inventory.sales,
    customer_id text NOT NULL,
    trace_id text NOT NULL,
    expires_at timestamptz NOT NULL,
    state text NOT NULL CHECK (state IN ('HELD','COMMITTED','RELEASED','EXPIRED'))
);
CREATE TABLE IF NOT EXISTS inventory.order_work (
    reservation_id text PRIMARY KEY REFERENCES inventory.reservations,
    body jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS inventory.events (
    event_id text PRIMARY KEY,
    body jsonb NOT NULL
);
COMMIT;

data.transactional-004_order_workflows.sql:
BEGIN;
SELECT pg_advisory_xact_lock(1);
SET LOCAL ROLE inventory_app;
ALTER TABLE inventory.order_work ADD COLUMN IF NOT EXISTS delivered_at timestamptz;
ALTER TABLE inventory.order_work ADD COLUMN IF NOT EXISTS next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp();
CREATE INDEX IF NOT EXISTS order_work_pending ON inventory.order_work(next_attempt_at,reservation_id) WHERE delivered_at IS NULL;
CREATE INDEX IF NOT EXISTS reservations_expiring ON inventory.reservations(expires_at,reservation_id) WHERE state='HELD';
CREATE TABLE IF NOT EXISTS inventory.outcomes (event_id text PRIMARY KEY, body jsonb NOT NULL);
RESET ROLE;
SET LOCAL ROLE orders_app;
CREATE TABLE IF NOT EXISTS orders.purchases (
    order_id text PRIMARY KEY,
    customer_id text NOT NULL,
    request bytea NOT NULL,
    state text NOT NULL DEFAULT 'PENDING' CHECK (state IN ('PENDING','CONFIRMED','CANCELLED')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS purchases_pending ON orders.purchases(next_attempt_at,order_id) WHERE state='PENDING';
CREATE TABLE IF NOT EXISTS orders.events (event_id text PRIMARY KEY, body jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS orders.outcomes (event_id text PRIMARY KEY, body jsonb NOT NULL);
RESET ROLE;
SET LOCAL ROLE payment_app;
CREATE TABLE IF NOT EXISTS payment.transactions (
    payment_id text PRIMARY KEY,
    request bytea NOT NULL,
    state text NOT NULL CHECK (state IN ('PENDING','SUCCEEDED','DECLINED','REFUNDED')),
    decision text NOT NULL CHECK (decision IN ('SUCCEEDED','DECLINED')),
    due_at timestamptz NOT NULL,
    lose_reply boolean NOT NULL
);
CREATE TABLE IF NOT EXISTS payment.events (event_id text PRIMARY KEY, body jsonb NOT NULL);
COMMIT;

data.transactional-005_event_delivery.sql:
BEGIN;
SELECT pg_advisory_xact_lock(1);
DO $$
DECLARE source text;
BEGIN
    FOREACH source IN ARRAY ARRAY['admission.events','inventory.events','inventory.outcomes','orders.events','orders.outcomes','payment.events'] LOOP
        EXECUTE format('ALTER TABLE %s ADD COLUMN IF NOT EXISTS delivered_at timestamptz,
            ADD COLUMN IF NOT EXISTS next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),
            ADD COLUMN IF NOT EXISTS delivery_attempts integer NOT NULL DEFAULT 0,
            ADD COLUMN IF NOT EXISTS dead_at timestamptz', source);
        EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %s (next_attempt_at,event_id) WHERE delivered_at IS NULL AND dead_at IS NULL',
            split_part(source,'.',2)||'_delivery_pending', source);
    END LOOP;
END $$;
COMMIT;

